def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('prefix',type=Path);a=p.parse_args()
    for suffix,value in [('.ac3',AC3),('.stereo.f32be',STEREO),('.surround.f32be',SURROUND)]:
        Path(str(a.prefix)+suffix).write_bytes(zlib.decompress(base64.b64decode(value)))
if __name__=='__main__':main()
